Rules.InvariantScript:
UpdateContext({varUrlPdfRea: "", varGerandoPdfRea: true});
IfError(
    With(
        {
            arquivoPdf: PDF(
                cntDocumentoRelatorioRea,
                {
                    Size: "A4",
                    DPI: 96,
                    ExpandContainers: true,
                    Orientation: "Portrait",
                    Margin: "12mm"
                }
            )
        },
        With(
            {
                respostaPdf: 'PowerAppV2->Criararquivo,Criarlinkdecompartilhamentoparaum...'.Run(
                    "Relatorio_REA_" & varRelatorioReaRegistro.TipodeOcorr_x00ea_ncia.Value,
                    {
                        file: {
                            contentBytes: arquivoPdf,
                            name: "Relatorio.pdf"
                        }
                    }
                )
            },
            If(
                IsBlank(respostaPdf.url),
                Notify("O fluxo não retornou o link do PDF.", NotificationType.Error),
                UpdateContext({varUrlPdfRea: respostaPdf.url});
                Notify("PDF criado. Clique em Abrir PDF.", NotificationType.Success)
            );
            true
        )
    ),
    Notify("Falha ao criar PDF: " & FirstError.Message, NotificationType.Error);
    false
);
UpdateContext({varGerandoPdfRea: false})
